"""Independent, deliberately naive reference implementations (dev only)."""


def ref_replay(req):
    caps = req['capacities']
    flows = {f['id']: f for f in req['flows']}
    tables = {}
    enabled = set()
    results = []
    for ev in req['events']:
        op = ev['op']
        if op == 'put':
            f = flows[ev['flow']]
            node = ev['node']
            i = f['path'].index(node)
            label = f['labels'][i]
            key = (node, label)
            if tables.get(key) == f['id']:
                st = 'ok'
            elif key in tables and tables[key] in enabled:
                st = 'busy'
            elif key not in tables and sum(1 for (n, l) in tables if n == node) >= caps[node]:
                st = 'full'
            else:
                tables[key] = f['id']
                st = 'ok'
            results.append({'status': st})
        elif op == 'enable':
            f = flows[ev['flow']]
            if all(tables.get((nd, f['labels'][i])) == f['id'] for i, nd in enumerate(f['path'])):
                enabled.add(f['id'])
                results.append({'status': 'ok'})
            else:
                results.append({'status': 'unready'})
        elif op == 'disable':
            enabled.discard(ev['flow'])
            results.append({'status': 'ok'})
        elif op == 'reset':
            enabled.clear()
            results.append({'status': 'ok'})
        else:
            fid = ev['flow']
            f = flows[fid]
            hdr = bytes.fromhex(ev['header'])
            pay = bytes.fromhex(ev['payload'])
            kinds = f['kinds']
            tmpl = bytes.fromhex(f['template'])
            qpos = kinds.index('Q')
            tpos = kinds.index('T')
            if fid not in enabled:
                mode, reason = 'ip', 'disabled'
            elif any(hdr[i] != tmpl[i] for i, ch in enumerate(kinds) if ch == 'K'):
                mode, reason = 'ip', 'mismatch'
            elif hdr[qpos] > 7:
                mode, reason = 'ip', 'qos'
            else:
                mode, reason = 'mpls', 'compressed'
            N = len(f['path'])
            ttl = hdr[tpos]
            wire = []
            delivered = None
            if ttl != 0:
                for j in range(N):
                    if mode == 'mpls':
                        residue = bytes(hdr[i] for i, ch in enumerate(kinds) if ch == 'D')
                        word = (f['labels'][j] << 12) | (hdr[qpos] << 9) | (1 << 8) | ttl
                        wire.append(word.to_bytes(4, 'big').hex() + residue.hex() + pay.hex())
                    else:
                        h2 = bytearray(hdr)
                        h2[tpos] = ttl
                        wire.append(h2.hex() + pay.hex())
                    if j == N - 1:
                        if mode == 'mpls':
                            out = bytearray(tmpl)
                            for i, ch in enumerate(kinds):
                                if ch == 'D':
                                    out[i] = hdr[i]
                                elif ch == 'Z':
                                    out[i] = 0
                                elif ch == 'Q':
                                    out[i] = hdr[qpos]
                                elif ch == 'T':
                                    out[i] = ttl
                                else:
                                    out[i] = tmpl[i]
                            delivered = out.hex() + pay.hex()
                        else:
                            h2 = bytearray(hdr)
                            h2[tpos] = ttl
                            delivered = h2.hex() + pay.hex()
                        break
                    if ttl <= 1:
                        break
                    ttl -= 1
            results.append({'mode': mode, 'reason': reason, 'wire': wire,
                            'delivered': delivered,
                            'byte_hops': sum(len(bytes.fromhex(w)) for w in wire)})
    active = sorted(enabled)
    tabs = sorted(({'node': n, 'label': l, 'flow': fid} for (n, l), fid in tables.items()),
                  key=lambda d: (d['node'], d['label']))
    return {'results': results, 'active': active, 'tables': tabs}


def plan_benefits(req):
    flows = req['flows']
    warmup = req['warmup']
    bens = {}
    for f in flows:
        kinds = f['kinds']
        tmpl = bytes.fromhex(f['template'])
        N = len(f['path'])
        h = N - 1
        qpos = kinds.index('Q')
        tpos = kinds.index('T')
        dc = kinds.count('D')
        per = (len(tmpl) - 4 - dc) * N
        idx = 0
        tot = 0
        for run in req['offers'][f['id']]:
            hb = bytes.fromhex(run['header'])
            cnt = run['count']
            ok = (all(hb[i] == tmpl[i] for i, ch in enumerate(kinds) if ch == 'K')
                  and hb[qpos] <= 7 and hb[tpos] > h)
            if ok:
                lo = max(idx, warmup)
                hi = idx + cnt
                if hi > lo:
                    tot += (hi - lo) * per
            idx += cnt
        bens[f['id']] = tot
    return bens


def ref_plan(req):
    caps = req['capacities']
    flows = req['flows']
    fmap = {f['id']: f for f in flows}
    bens = plan_benefits(req)
    pinned = req['pinned']
    for nd, c in caps.items():
        if sum(1 for p in pinned if nd in fmap[p]['path']) > c:
            return {'infeasible': True}
    ids = [f['id'] for f in flows]
    others = [i for i in ids if i not in set(pinned)]
    best = None
    for mask in range(1 << len(others)):
        sel = set(pinned) | {others[j] for j in range(len(others)) if mask >> j & 1}
        ok = True
        for nd, c in caps.items():
            if sum(1 for s in sel if nd in fmap[s]['path']) > c:
                ok = False
                break
        if not ok:
            continue
        ben = sum(bens[s] for s in sel)
        key = (-ben, len(sel))
        if best is None or key < best[0]:
            best = (key, sel)
    sel = best[1]
    return {'selected': sorted(sel), 'saved': sum(bens[s] for s in sel)}
