"""Random valid request generators (dev only)."""
import random

KINDS = 'KDZQT'


def rand_id(rng, pool=None):
    if pool is not None:
        return pool[rng.randrange(len(pool))]
    n = rng.randint(1, 6)
    return ''.join(rng.choice('abcdefghnmopqrstuvwxyz0123456789_.-') for _ in range(n))


def rand_kinds(rng, H):
    while True:
        k = list(rng.choice(KINDS) for _ in range(H))
        if k.count('Q') != 1 or k.count('T') != 1:
            pos = rng.sample(range(H), 2)
            k[pos[0]] = 'Q'
            k[pos[1]] = 'T'
        if k.count('Q') != 1 or k.count('T') != 1:
            continue
        if k.count('K') < 1:
            continue
        if 4 + k.count('D') >= H:
            continue
        return ''.join(k)


def rand_flow(rng, nodes, replay, H=None):
    H = H or rng.randint(8, 20)
    L = rng.randint(2, min(9, len(nodes)))
    path = rng.sample(nodes, L)
    kinds = rand_kinds(rng, H)
    tmpl = bytes(rng.randrange(256) for _ in range(H))
    f = {'id': None, 'path': path, 'template': tmpl.hex(), 'kinds': kinds}
    if replay:
        f['labels'] = [rng.choice([16, 17, 20, 100, 1048575, rng.randint(16, 1048575)])
                       for _ in path]
    return f


def make_replay(rng, nflows=None, nev=None):
    nnodes = rng.randint(2, 8)
    nodes = ['n%d' % i for i in range(nnodes)]
    caps = {n: rng.choice([0, 1, 1, 2, 2, 3, 5]) for n in nodes}
    nf = nflows if nflows is not None else rng.randint(0, 5)
    flows = []
    for i in range(nf):
        f = rand_flow(rng, nodes, True)
        f['id'] = 'f%d' % i
        flows.append(f)
    events = []
    ne = nev if nev is not None else rng.randint(0, 40)
    for _ in range(ne):
        r = rng.random()
        if not flows:
            events.append({'op': 'reset'})
            continue
        f = rng.choice(flows)
        if r < 0.3:
            events.append({'op': 'put', 'flow': f['id'], 'node': rng.choice(f['path'])})
        elif r < 0.45:
            events.append({'op': 'enable', 'flow': f['id']})
        elif r < 0.55:
            events.append({'op': 'disable', 'flow': f['id']})
        elif r < 0.6:
            events.append({'op': 'reset'})
        else:
            hdr = bytearray(bytes.fromhex(f['template']))
            kinds = f['kinds']
            H = len(hdr)
            qpos = kinds.index('Q')
            tpos = kinds.index('T')
            style = rng.random()
            if style < 0.4:      # matching K
                for i, ch in enumerate(kinds):
                    if ch != 'K':
                        hdr[i] = rng.randrange(256)
                hdr[qpos] = rng.choice([0, 1, 3, 7, 8, 9, 200, 255])
            elif style < 0.7:    # mutate a K byte sometimes
                for i, ch in enumerate(kinds):
                    if ch != 'K' and rng.random() < 0.8:
                        hdr[i] = rng.randrange(256)
                if rng.random() < 0.6:
                    kpos = [i for i, ch in enumerate(kinds) if ch == 'K']
                    hdr[rng.choice(kpos)] = (hdr[rng.choice(kpos)] + rng.randint(1, 255)) % 256
                hdr[qpos] = rng.choice([0, 1, 3, 7, 8, 255])
            else:
                hdr = bytearray(rng.randrange(256) for _ in range(H))
            hdr[tpos] = rng.choice([0, 1, 2, 3, 4, 8, 200, 255, rng.randint(0, 12)])
            pay = bytes(rng.randrange(256) for _ in range(rng.choice([0, 0, 1, 3, 8])))
            events.append({'op': 'packet', 'flow': f['id'], 'header': hdr.hex(),
                           'payload': pay.hex()})
    return {'mode': 'replay', 'capacities': caps, 'flows': flows, 'events': events}


def make_plan(rng, nflows=None):
    nnodes = rng.randint(2, 9)
    nodes = ['n%d' % i for i in range(nnodes)]
    caps = {n: rng.choice([0, 1, 1, 2, 2, 3, 4, 6]) for n in nodes}
    nf = nflows if nflows is not None else rng.randint(0, 10)
    flows = []
    for i in range(nf):
        f = rand_flow(rng, nodes, False)
        f['id'] = 'f%d' % i
        flows.append(f)
    warmup = rng.choice([0, 0, 1, 2, 5, 100])
    pinned = [f['id'] for f in flows if rng.random() < 0.15]
    offers = {}
    for f in flows:
        kinds = f['kinds']
        tmpl = bytes.fromhex(f['template'])
        H = len(tmpl)
        qpos = kinds.index('Q')
        tpos = kinds.index('T')
        runs = []
        for _ in range(rng.randint(0, 4)):
            hdr = bytearray(tmpl)
            for i, ch in enumerate(kinds):
                if ch != 'K' and rng.random() < 0.8:
                    hdr[i] = rng.randrange(256)
            if rng.random() < 0.25:
                kpos = [i for i, ch in enumerate(kinds) if ch == 'K']
                hdr[rng.choice(kpos)] ^= 0xff
            hdr[qpos] = rng.choice([0, 3, 7, 8, 200])
            hdr[tpos] = rng.choice([0, 1, 2, 3, 5, 20, 255])
            runs.append({'header': hdr.hex(), 'count': rng.choice([1, 2, 5, 1000, 10 ** 9])})
        offers[f['id']] = runs
    return {'mode': 'plan', 'capacities': caps, 'flows': flows, 'warmup': warmup,
            'pinned': pinned, 'offers': offers}
