"""Cross-check candidate against reference on random requests (dev only)."""
import json
import random
import subprocess
import sys
sys.path.insert(0, '/workspace/dev')
import ref
import gen

CAND = '/workspace/submission/main.py'


def run_candidate(lines):
    data = ''.join(l + '\n' for l in lines)
    p = subprocess.run([sys.executable, '-I', '-B', CAND], input=data, text=True,
                       capture_output=True, timeout=200)
    if p.returncode:
        raise SystemExit('candidate exited %d stderr=%s' % (p.returncode, p.stderr[:2000]))
    return p.stdout.splitlines()


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    iters = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    replays = []
    plans = []
    for _ in range(iters):
        replays.append(gen.make_replay(rng))
    for _ in range(iters):
        plans.append(gen.make_plan(rng, nflows=rng.randint(0, 12)))
    lines = [json.dumps(r) for r in replays] + [json.dumps(p) for p in plans]
    out = run_candidate(lines)
    assert len(out) == len(lines), (len(out), len(lines))
    bad = 0
    for i, r in enumerate(replays):
        got = json.loads(out[i])
        exp = ref.ref_replay(r)
        if got != exp:
            bad += 1
            print('REPLAY MISMATCH idx', i)
            print(json.dumps(r)[:3000])
            for a, b in zip(got.get('results', []), exp['results']):
                if a != b:
                    print(' got', json.dumps(a)[:400])
                    print(' exp', json.dumps(b)[:400])
                    break
            else:
                print(' got tail', json.dumps({k: v for k, v in got.items() if k != 'results'})[:600])
                print(' exp tail', json.dumps({k: v for k, v in exp.items() if k != 'results'})[:600])
            if bad > 2:
                break
    for i, p in enumerate(plans):
        got = json.loads(out[len(replays) + i])
        exp = ref.ref_plan(p)
        if 'infeasible' in exp:
            if got != exp:
                print('PLAN INFEAS MISMATCH', json.dumps(p)[:2000], got, exp)
                bad += 1
            continue
        if got.get('saved') != exp['saved'] or len(got.get('selected', [])) != len(exp['selected']):
            print('PLAN MISMATCH idx', i)
            print(json.dumps(p)[:2000])
            print(' got', got)
            print(' exp', exp)
            bad += 1
        else:
            # verify feasibility of returned set
            fmap = {f['id']: f for f in p['flows']}
            for nd, c in p['capacities'].items():
                if sum(1 for s in got['selected'] if nd in fmap[s]['path']) > c:
                    print('PLAN INFEASIBLE SELECTION', nd, json.dumps(p)[:800], got)
                    bad += 1
            if set(got['selected']) != set(got['selected']) or len(set(got['selected'])) != len(got['selected']):
                print('dup selected', got)
                bad += 1
            if sorted(got['selected']) != got['selected']:
                print('not sorted', got)
                bad += 1
            if not set(exp['selected']) <= set(got['selected']):
                pass  # pinned must be included
            for pid in p['pinned']:
                if pid not in got['selected']:
                    print('missing pinned', pid, got)
                    bad += 1
            b = ref.plan_benefits(p)
            if sum(b[s] for s in got['selected']) != got['saved']:
                print('saved mismatch recompute', got, sum(b[s] for s in got['selected']))
                bad += 1
        if bad > 4:
            break
    print('done bad =', bad)


