def run():
    inp = sys.stdin.buffer
    out = sys.stdout.buffer
    write = out.write
    loads = json.loads
    dumps = json.dumps
    for raw in inp:
        if len(raw) > MAX_LINE or not raw.strip():
            resp = ERR
        else:
            try:
                obj = loads(raw, parse_float=_rej, parse_constant=_rej,
                            object_pairs_hook=_pairs)
                resp = dumps(handle(obj), separators=(',', ':')).encode() + b'\n'
            except Exception:
                resp = ERR
        try:
            write(resp)
            out.flush()
        except Exception:
            break
    try:
        out.flush()
    except Exception:
        pass


if __name__ == '__main__':
    run()
